import json
from urllib.request import Request, urlopen

MCPS = {
    \"sentry\":   \"http://mcp-sentry:7002/mcp\",
    \"grafana\":  \"http://mcp-grafana:8000/mcp\",
    \"gke\":      \"http://mcp-gke:7004/mcp\",
    \"logging\":  \"http://mcp-logging:7005/mcp\",
    \"postgres\": \"http://mcp-postgres:7006/mcp\",
    \"github\":   \"http://mcp-github:7007/mcp\",
}

PROBLEM_KEYS = (\"deprecated\", \"readOnly\", \"writeOnly\")

def find_problem_keys(obj, path=\"\"):
    issues = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            if k in PROBLEM_KEYS or k.startswith(\"x-\"):
                issues.append((path + \".\" + k, k))
            issues.extend(find_problem_keys(v, path + \".\" + k))
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            issues.extend(find_problem_keys(item, path + f\"[{i}]\"))
    return issues

# Try MCP tools/list via JSON-RPC
def list_tools(name, url):
    body = {\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"initialize\",\"params\":{\"protocolVersion\":\"2025-06-18\",\"capabilities\":{},\"clientInfo\":{\"name\":\"diag\",\"version\":\"1\"}}}
    try:
        # Init session
        req = Request(url, data=json.dumps(body).encode(), headers={\"Content-Type\":\"application/json\",\"Accept\":\"application/json,text/event-stream\"})
        urlopen(req, timeout=5).read()
        # List tools
        body = {\"jsonrpc\":\"2.0\",\"id\":2,\"method\":\"tools/list\"}
        req = Request(url, data=json.dumps(body).encode(), headers={\"Content-Type\":\"application/json\",\"Accept\":\"application/json,text/event-stream\"})
        resp = urlopen(req, timeout=10).read().decode()
        # Try parse
        try:
            return json.loads(resp)
        except:
            for line in resp.split(\"\\n\"):
                if line.startswith(\"data:\"):
                    return json.loads(line[5:])
            return None
    except Exception as e:
        return {\"error\": str(e)}

for name, url in MCPS.items():
    r = list_tools(name, url)
    if r is None or \"error\" in (r or {}):
        print(f\"{name:10} ERROR {r}\")
        continue
    tools = r.get(\"result\", {}).get(\"tools\", [])
    bad = []
    for t in tools:
        issues = find_problem_keys(t.get(\"inputSchema\", {}))
        if issues:
            bad.append((t[\"name\"], len(issues), issues[:2]))
    print(f\"{name:10} tools={len(tools):3} with_problem_keys={len(bad)}\")
    for tname, count, sample in bad[:3]:
        print(f\"  {tname}: {count} issues, sample: {sample}\")
"' 2>&1 | head -80

